using System.Net;using System.Net.Http.Headers;using System.Net.Http.Json;using System.Text.Json;using FluentAssertions;namespace VetCommission.IntegrationTests.WebApi;[Collection(WebApiCollection.Name)]public sealed class CommissionConfigurationEndpointTests(WebApiTestFactory factory){const string Tenant="11111111-1111-1111-1111-111111111111";const string Clinic="77777777-7777-7777-7777-777777777771";[Fact]public async Task Competency_CanListAndClose(){using var c=await Client();var list=await c.GetAsync("/api/competencias");list.StatusCode.Should().Be(HttpStatusCode.OK);var create=await c.PostAsJsonAsync("/api/competencias",new{year=2026,month=9});create.StatusCode.Should().Be(HttpStatusCode.OK);using var p=JsonDocument.Parse(await create.Content.ReadAsStringAsync());var id=p.RootElement.GetProperty("id").GetGuid();var close=await c.PostAsync($"/api/competencias/{id}/fechar",null);close.StatusCode.Should().Be(HttpStatusCode.OK);}async Task<HttpClient>Client(){var c=factory.CreateClient();var l=await c.PostAsJsonAsync("/api/auth/login",new{email="admin@vetcommission.local",senha="qwas"});l.EnsureSuccessStatusCode();using var p=JsonDocument.Parse(await l.Content.ReadAsStringAsync());c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",p.RootElement.GetProperty("accessToken").GetString());c.DefaultRequestHeaders.Add("X-Tenant-Id",Tenant);c.DefaultRequestHeaders.Add("X-Clinic-Id",Clinic);return c;}}
